APP_CSS = r"""
<style>
@import url('https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.css');
:root{--blue:#2563EB;--blue2:#1D4ED8;--soft:#EFF6FF;--ink:#172033;--muted:#667085;--bg:#F6F8FB;--line:#E5EAF1;--green:#059669;--greens:#ECFDF5;--amber:#D97706;--ambers:#FFFBEB}
html,body,[class*="css"]{font-family:'Pretendard',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif}#MainMenu,footer,header{visibility:hidden}.stApp{background:var(--bg)}.block-container{max-width:1280px;padding-top:2rem;padding-bottom:3rem}
[data-testid="stSidebar"]{background:#F9FBFE!important;border-right:1px solid var(--line)}[data-testid="stSidebar"] *{letter-spacing:-.01em}[data-testid="stSidebar"] h1,[data-testid="stSidebar"] h2,[data-testid="stSidebar"] h3{color:var(--ink)!important}[data-testid="stSidebar"] label,[data-testid="stSidebar"] p,[data-testid="stSidebar"] .stCaption{color:#475467!important}[data-testid="stSidebar"] hr{border-color:var(--line)}
[data-testid="stSidebar"] [data-testid="stFileUploaderDropzone"],[data-testid="stSidebar"] [data-testid="stFileUploadDropzone"]{background:#fff!important;border:1px dashed #B8C7DD!important;border-radius:12px!important}[data-testid="stSidebar"] [data-testid="stFileUploaderDropzone"] *,[data-testid="stSidebar"] [data-testid="stFileUploadDropzone"] *{color:#344054!important;fill:#344054!important}
div.stButton>button,div.stDownloadButton>button{border-radius:10px!important;min-height:42px;font-weight:700;transition:.15s ease}div.stButton>button{background:var(--blue);color:white;border:1px solid var(--blue)}div.stButton>button:hover{background:var(--blue2);border-color:var(--blue2);transform:translateY(-1px)}div.stDownloadButton>button{background:#fff;color:var(--blue);border:1px solid #BFD1F7;width:100%}div.stDownloadButton>button:hover{background:var(--soft);border-color:#8CB0F5}
.app-head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start;margin-bottom:22px}.app-brand{display:flex;gap:13px;align-items:center}.app-logo{width:44px;height:44px;border-radius:12px;background:var(--blue);display:flex;align-items:center;justify-content:center;color:#fff;font-size:21px;box-shadow:0 6px 16px rgba(37,99,235,.18)}.app-title{font-size:1.55rem;font-weight:800;color:var(--ink);letter-spacing:-.035em}.app-sub{font-size:.88rem;color:var(--muted);margin-top:3px}.live-chip{background:#fff;border:1px solid var(--line);border-radius:999px;padding:7px 12px;font-size:.78rem;color:#475467;white-space:nowrap}
.flow{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:4px 0 22px}.flow-step{background:#fff;border:1px solid var(--line);border-radius:12px;padding:13px 14px;min-height:72px}.flow-step.active{border-color:#9DBAF6;background:var(--soft)}.flow-no{font-size:.72rem;font-weight:800;color:var(--blue);margin-bottom:4px}.flow-title{font-size:.86rem;font-weight:750;color:var(--ink)}.flow-desc{font-size:.73rem;color:var(--muted);margin-top:3px;line-height:1.35}
.kpi-row{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px}.kpi-card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:17px 18px;box-shadow:0 1px 2px rgba(16,24,40,.025)}.kpi-label{font-size:.78rem;color:var(--muted);font-weight:650;margin-bottom:7px}.kpi-value{font-size:1.55rem;font-weight:800;color:var(--ink);letter-spacing:-.035em}.kpi-unit{font-size:.83rem;color:var(--muted);font-weight:600;margin-left:3px}.kpi-note{font-size:.74rem;color:var(--muted);margin-top:5px}
.work-card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:18px 20px;margin-bottom:16px}.work-title{font-size:.95rem;font-weight:800;color:var(--ink);margin-bottom:6px}.work-desc{font-size:.82rem;color:var(--muted);line-height:1.6}.status{display:inline-flex;align-items:center;border-radius:999px;padding:5px 10px;font-size:.76rem;font-weight:750}.status.ok{background:var(--greens);color:var(--green)}.status.warn{background:var(--ambers);color:var(--amber)}.status.info{background:var(--soft);color:var(--blue)}
.region-card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:17px 18px;margin-top:16px}.region-track{height:9px;background:#EEF2F7;border-radius:999px;overflow:hidden;display:flex;margin:11px 0 9px}.region-seg-1{background:#2563EB}.region-seg-2{background:#14B8A6}.region-seg-3{background:#CBD5E1}.region-legend{display:flex;gap:18px;flex-wrap:wrap;font-size:.76rem;color:var(--muted)}.side-section{font-size:.78rem;font-weight:800;color:#344054;margin:2px 0 8px}.side-help{font-size:.72rem;color:#667085;line-height:1.5;margin-top:5px}
.waiting-card{max-width:480px;margin:80px auto;background:#fff;border:1px solid var(--line);border-radius:18px;text-align:center;padding:38px}.waiting-icon{font-size:2rem}.waiting-title{font-size:1.05rem;font-weight:800;color:var(--ink);margin:10px 0 5px}.waiting-desc{font-size:.86rem;color:var(--muted)}.waiting-meta{font-size:.75rem;color:#98A2B3;margin-top:12px}
@media(max-width:900px){.flow,.kpi-row{grid-template-columns:1fr 1fr}.app-head{display:block}.live-chip{display:inline-block;margin-top:10px}}@media(max-width:640px){.flow,.kpi-row{grid-template-columns:1fr}}
</style>
"""
